// Demo: Hardware Watchdog Timers — timeout vs pet interval
var timeout=2,pet=timeout/3;
console.log('technique: Hardware Watchdog Timers');console.log('timeout: '+timeout+' ms, pet interval: '+pet+' ms');
console.log('margin: '+(timeout-pet)+' ms — pet at 1/3 timeout for safety');
console.log(pet<timeout/2?'safe: even one missed pet will not fire':'RISKY: a single delay fires the watchdog');

// Demo: Windowed Watchdogs — windowed watchdog check
var t=10%90+5,min=10,max=100;
console.log('technique: Windowed Watchdogs');console.log('pet at t='+t+' ms, window ['+min+', '+max+']');
console.log(t>=min&&t<=max?'pet accepted':'PET REJECTED — too early or too late fires the watchdog');

